'use client';

import { useState, useCallback } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import * as THREE from 'three';
import { useDesignStore } from '@/lib/store';
import { Room } from './Room';
import { Lighting } from './Lighting';
import { SceneObject } from './SceneObject';

// Floor plane for raycasting - y=0
const floorPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);

export function Scene3D() {
  const { currentDesign, selectedObjectId, selectObject, setCameraPosition, updateObject } = useDesignStore();
  const [isDragging, setIsDragging] = useState(false);

  if (!currentDesign) return null;

  return (
    <div className="w-full h-full bg-gradient-to-b from-gray-900 to-gray-800">
      <Canvas
        camera={{ position: [0, 12, 25], fov: 60 }}
        shadows
        gl={{ antialias: true }}
      >
        <color attach="background" args={['#1a1a2e']} />
        <fog attach="fog" args={['#1a1a2e', 20, 100]} />
        
        <Lighting preset={currentDesign.roomSettings.lightingPreset} />
        
        {/* Environment - NEVER moves */}
        <group name="environment">
          <Room
            settings={currentDesign.roomSettings}
            templateId={currentDesign.templateId}
          />
        </group>
        
        {/* Objects - separate group, draggable */}
        <group name="objects">
          {currentDesign.objects.map((obj) => (
            <SceneObject
              key={obj.id}
              object={obj}
              isSelected={obj.id === selectedObjectId}
              onClick={() => selectObject(obj.id)}
              onDragStateChange={setIsDragging}
              floorPlane={floorPlane}
            />
          ))}
        </group>
        
        <OrbitControls
          enabled={!isDragging}
          enablePan={true}
          enableZoom={true}
          enableRotate={true}
          minDistance={5}
          maxDistance={60}
          maxPolarAngle={Math.PI / 2 - 0.05}
          onChange={(e) => {
            if (e?.target) {
              const pos = e.target.object.position;
              setCameraPosition({ x: pos.x, z: pos.z });
            }
          }}
        />
      </Canvas>
    </div>
  );
}
