'use client';

import { useRef, useMemo, useState, useCallback, useEffect } from 'react';
import * as THREE from 'three';
import { useFrame, useThree } from '@react-three/fiber';
import type { SceneObject as SceneObjectType } from '@/lib/types';
import { useDesignStore } from '@/lib/store';

interface SceneObjectProps {
  object: SceneObjectType;
  isSelected: boolean;
  onClick: () => void;
  onDragStateChange?: (isDragging: boolean) => void;
  floorPlane: THREE.Plane;
}

export function SceneObject({ object, isSelected, onClick, onDragStateChange, floorPlane }: SceneObjectProps) {
  const groupRef = useRef<THREE.Group>(null);
  const { updateObject, currentDesign, setLastInteractionPoint } = useDesignStore();
  const { camera, gl } = useThree();
  const [isDragging, setIsDragging] = useState(false);
  
  // Drag offset to prevent object jumping to cursor
  const dragOffset = useRef({ x: 0, z: 0 });

  // Get child chairs for tables
  const childChairs = useMemo(() => {
    if (!currentDesign || (object.type !== 'round-table' && object.type !== 'rect-table')) {
      return [];
    }
    return currentDesign.objects.filter(
      obj => obj.parentTableId === object.id && obj.isAutoGenerated
    );
  }, [currentDesign, object.id, object.type]);

  // Selection animation - gentle bounce
  useFrame(() => {
    if (groupRef.current && isSelected && !isDragging) {
      const time = Date.now() * 0.002;
      groupRef.current.position.y = object.position[1] + Math.sin(time) * 0.05;
    } else if (groupRef.current) {
      groupRef.current.position.y = object.position[1];
    }
  });

  // Raycast to floor plane
  const getFloorPosition = useCallback((clientX: number, clientY: number): [number, number] | null => {
    if (!camera || !gl?.domElement) return null;
    
    const rect = gl.domElement.getBoundingClientRect();
    const mouse = new THREE.Vector2(
      ((clientX - rect.left) / rect.width) * 2 - 1,
      -((clientY - rect.top) / rect.height) * 2 + 1
    );

    const raycaster = new THREE.Raycaster();
    raycaster.setFromCamera(mouse, camera);

    const target = new THREE.Vector3();
    const hit = raycaster.ray.intersectPlane(floorPlane, target);

    if (hit) {
      return [target.x, target.z];
    }
    return null;
  }, [camera, gl, floorPlane]);

  // Handle pointer down - start drag
  const handlePointerDown = (e: any) => {
    if (!e) return;
    e.stopPropagation();
    onClick();

    const nativeEvent = e.nativeEvent as PointerEvent;
    const floorPos = getFloorPosition(nativeEvent.clientX, nativeEvent.clientY);

    if (floorPos) {
      dragOffset.current = {
        x: object.position[0] - floorPos[0],
        z: object.position[2] - floorPos[1],
      };
    }

    setIsDragging(true);
    onDragStateChange?.(true);

    const target = e.target;
    if (target && typeof target.setPointerCapture === 'function' && nativeEvent?.pointerId !== undefined) {
      target.setPointerCapture(nativeEvent.pointerId);
    }
  };

  // Handle pointer move - perform drag
  const handlePointerMove = (e: any) => {
    if (!isDragging || !e) return;
    e.stopPropagation();

    const nativeEvent = e.nativeEvent as PointerEvent;
    const floorPos = getFloorPosition(nativeEvent.clientX, nativeEvent.clientY);

    if (!floorPos) return;

    // NO SNAPPING - continuous movement
    const newX = floorPos[0] + dragOffset.current.x;
    const newZ = floorPos[1] + dragOffset.current.z;

    // For tables: move table AND child chairs together
    if (object.type === 'round-table' || object.type === 'rect-table') {
      const tableDeltaX = newX - object.position[0];
      const tableDeltaZ = newZ - object.position[2];

      updateObject(object.id, { position: [newX, 0, newZ] });

      childChairs.forEach(chair => {
        if (!chair?.position) return;
        updateObject(chair.id, {
          position: [
            chair.position[0] + tableDeltaX,
            0,
            chair.position[2] + tableDeltaZ,
          ],
        });
      });
    } else {
      updateObject(object.id, { position: [newX, 0, newZ] });
    }
  };

  // Handle pointer up - end drag
  const handlePointerUp = (e: any) => {
    if (!isDragging || !e) return;
    e.stopPropagation();

    setIsDragging(false);
    onDragStateChange?.(false);
    setLastInteractionPoint({ x: object.position[0], z: object.position[2] });

    const nativeEvent = e.nativeEvent as PointerEvent;
    const target = e.target;
    if (target && typeof target.releasePointerCapture === 'function' && nativeEvent?.pointerId !== undefined) {
      target.releasePointerCapture(nativeEvent.pointerId);
    }
  };

  return (
    <group
      ref={groupRef}
      position={object.position}
      rotation={object.rotation}
      scale={object.scale}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onClick={(e) => {
        e.stopPropagation();
        onClick();
      }}
    >
      {/* Selection outline */}
      {isSelected && (
        <mesh scale={[1.1, 1.1, 1.1]}>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="#C6A85C" wireframe transparent opacity={0.5} />
        </mesh>
      )}

      <ObjectMesh
        type={object.type}
        color={object.color}
        material={object.material}
        style={object.style}
        isSelected={isSelected}
        seatingCapacity={object.seatingCapacity}
      />
    </group>
  );
}

// ObjectMesh component stays the same
function ObjectMesh({
  type,
  color,
  material,
  style,
  isSelected,
  seatingCapacity,
}: {
  type: string;
  color: string;
  material?: string;
  style?: string;
  isSelected?: boolean;
  seatingCapacity?: number;
}) {
  const matProps = useMemo(() => {
    if (material === 'wood') return { roughness: 0.8, metalness: 0 };
    if (material === 'metal') return { roughness: 0.2, metalness: 0.8 };
    if (material === 'glass') return { roughness: 0, metalness: 0.1, transparent: true, opacity: 0.6 };
    if (material === 'fabric') return { roughness: 0.9, metalness: 0 };
    return { roughness: 0.5, metalness: 0.1 };
  }, [material]);

  const getTableRadius = (capacity?: number): number => {
    if (!capacity || capacity <= 6) return 1.2;
    if (capacity <= 8) return 1.5;
    if (capacity <= 10) return 1.8;
    return 2.1;
  };

  const getRectDimensions = (capacity?: number): { width: number; depth: number } => {
    if (!capacity || capacity <= 4) return { width: 3, depth: 2 };
    if (capacity <= 6) return { width: 4, depth: 2 };
    if (capacity <= 8) return { width: 5, depth: 2 };
    if (capacity <= 10) return { width: 6, depth: 2.2 };
    return { width: 7, depth: 2.4 };
  };

  switch (type) {
    case 'round-table': {
      const radius = getTableRadius(seatingCapacity);
      const drapeRadius = radius + 0.1;
      return (
        <group>
          <mesh castShadow receiveShadow position={[0, 0.75, 0]}>
            <cylinderGeometry args={[radius, radius, 0.1, 32]} />
            <meshStandardMaterial color={color} {...matProps} />
          </mesh>
          <mesh position={[0, 0.45, 0]} castShadow>
            <cylinderGeometry args={[drapeRadius, radius - 0.1, 0.6, 32]} />
            <meshStandardMaterial color={color} {...matProps} />
          </mesh>
          <mesh position={[0, -0.5, 0]} castShadow>
            <cylinderGeometry args={[radius * 0.2, radius * 0.33, 1.5, 16]} />
            <meshStandardMaterial color="#8B4513" roughness={0.8} />
          </mesh>
          {isSelected && (
            <mesh position={[0, 0.05, 0]} rotation={[-Math.PI / 2, 0, 0]}>
              <ringGeometry args={[drapeRadius, drapeRadius + 0.1, 32]} />
              <meshBasicMaterial color="#C6A85C" transparent opacity={0.8} />
            </mesh>
          )}
        </group>
      );
    }

    case 'rect-table': {
      const { width, depth } = getRectDimensions(seatingCapacity);
      const halfWidth = width / 2;
      const halfDepth = depth / 2;
      const legX = halfWidth - 0.2;
      const legZ = halfDepth - 0.2;
      return (
        <group>
          <mesh castShadow receiveShadow position={[0, 0.75, 0]}>
            <boxGeometry args={[width, 0.1, depth]} />
            <meshStandardMaterial color={color} {...matProps} />
          </mesh>
          <mesh position={[0, 0.45, 0]} castShadow>
            <boxGeometry args={[width + 0.1, 0.6, depth + 0.1]} />
            <meshStandardMaterial color={color} {...matProps} />
          </mesh>
          {([
            [-legX, 0, -legZ],
            [legX, 0, -legZ],
            [-legX, 0, legZ],
            [legX, 0, legZ],
          ] as [number, number, number][]).map((pos, i) => (
            <mesh key={i} position={pos} castShadow>
              <cylinderGeometry args={[0.1, 0.1, 1.8, 8]} />
              <meshStandardMaterial color="#8B4513" roughness={0.8} />
            </mesh>
          ))}
          {isSelected && (
            <mesh position={[0, 0.05, 0]}>
              <boxGeometry args={[width + 0.3, 0.02, depth + 0.3]} />
              <meshBasicMaterial color="#C6A85C" transparent opacity={0.5} />
            </mesh>
          )}
        </group>
      );
    }

    case 'chair':
      return (
        <group>
          <mesh position={[0, 0.45, 0]} castShadow>
            <boxGeometry args={[0.5, 0.1, 0.5]} />
            <meshStandardMaterial color={color} {...matProps} />
          </mesh>
          <mesh position={[0, 0.52, 0]} castShadow>
            <boxGeometry args={[0.5, 0.05, 0.5]} />
            <meshStandardMaterial color={color} {...matProps} />
          </mesh>
          <mesh position={[0, 0.9, -0.2]} castShadow>
            <boxGeometry args={[0.5, 0.8, 0.08]} />
            <meshStandardMaterial color={color} {...matProps} />
          </mesh>
          {([
            [-0.22, 0.225, -0.22],
            [0.22, 0.225, -0.22],
            [-0.22, 0.225, 0.22],
            [0.22, 0.225, 0.22],
          ] as [number, number, number][]).map((pos, i) => (
            <mesh key={i} position={pos} castShadow>
              <cylinderGeometry args={[0.04, 0.04, 0.45, 8]} />
              <meshStandardMaterial color="#8B4513" roughness={0.8} />
            </mesh>
          ))}
          {isSelected && (
            <mesh position={[0, 0.5, 0]}>
              <boxGeometry args={[0.7, 1.1, 0.7]} />
              <meshBasicMaterial color="#C6A85C" wireframe transparent opacity={0.5} />
            </mesh>
          )}
        </group>
      );

    case 'balloon-arch':
      return (
        <group>
          <mesh position={[0, 2.5, 0]}>
            <boxGeometry args={[7, 5, 2]} />
            <meshBasicMaterial visible={false} />
          </mesh>
          {[...Array(15)].map((_, i) => {
            const t = i / 14;
            const angle = t * Math.PI;
            const x = Math.cos(angle) * 3;
            const y = Math.sin(angle) * 3 + 1;
            const z = 0;
            return (
              <mesh key={i} position={[x, y, z]} castShadow>
                <sphereGeometry args={[0.4, 16, 16]} />
                <meshStandardMaterial
                  color={style === 'ombre' ?
                    new THREE.Color().setHSL((i / 15), 0.8, 0.6).toString() :
                    color
                  }
                  roughness={0.3}
                  metalness={0.1}
                />
              </mesh>
            );
          })}
          {isSelected && (
            <mesh position={[0, 2.5, 0]}>
              <boxGeometry args={[7.2, 5.2, 2.2]} />
              <meshBasicMaterial color="#C6A85C" wireframe transparent opacity={0.3} />
            </mesh>
          )}
        </group>
      );

    case 'balloon-column':
      return (
        <group>
          <mesh position={[0, 2.5, 0]}>
            <cylinderGeometry args={[0.6, 0.6, 5.5, 16]} />
            <meshBasicMaterial visible={false} />
          </mesh>
          {[...Array(8)].map((_, i) => (
            <mesh key={i} position={[0, i * 0.6 + 0.5, 0]} castShadow>
              <sphereGeometry args={[0.35, 16, 16]} />
              <meshStandardMaterial
                color={style === 'spiral' ?
                  (i % 2 === 0 ? color : '#ffffff') :
                  color
                }
                roughness={0.3}
              />
            </mesh>
          ))}
          {isSelected && (
            <mesh position={[0, 2.5, 0]}>
              <cylinderGeometry args={[0.7, 0.7, 5.7, 16]} />
              <meshBasicMaterial color="#C6A85C" wireframe transparent opacity={0.3} />
            </mesh>
          )}
        </group>
      );

    case 'centerpiece':
      return (
        <group>
          <mesh position={[0, 0.6, 0]}>
            <boxGeometry args={[0.8, 1.2, 0.8]} />
            <meshBasicMaterial visible={false} />
          </mesh>
          {style === 'floral' ? (
            <>
              <mesh position={[0, 0.3, 0]} castShadow>
                <cylinderGeometry args={[0.15, 0.2, 0.6, 16]} />
                <meshStandardMaterial color="#ffffff" {...matProps} />
              </mesh>
              {([
                [0, 0.8, 0],
                [0.2, 0.7, 0.1],
                [-0.2, 0.75, -0.1],
                [0.1, 0.9, -0.2],
              ] as [number, number, number][]).map((pos, i) => (
                <mesh key={i} position={pos} castShadow>
                  <sphereGeometry args={[0.15, 8, 8]} />
                  <meshStandardMaterial color={['#FF69B4', '#FFB6C1', '#FFC0CB', '#FF1493'][i]} />
                </mesh>
              ))}
            </>
          ) : (
            <mesh castShadow>
              <cylinderGeometry args={[0.3, 0.3, 0.5, 16]} />
              <meshStandardMaterial color={color} {...matProps} />
            </mesh>
          )}
          {isSelected && (
            <mesh position={[0, 0.6, 0]}>
              <boxGeometry args={[0.9, 1.4, 0.9]} />
              <meshBasicMaterial color="#C6A85C" wireframe transparent opacity={0.3} />
            </mesh>
          )}
        </group>
      );

    case 'spotlight':
      return (
        <group>
          <mesh position={[0, 0.5, 0]}>
            <boxGeometry args={[0.8, 2.5, 0.8]} />
            <meshBasicMaterial visible={false} />
          </mesh>
          <mesh position={[0, 0.5, 0]} castShadow>
            <coneGeometry args={[0.3, 0.5, 16]} />
            <meshStandardMaterial color="#333333" metalness={0.8} roughness={0.2} />
          </mesh>
          <mesh position={[0, -1, 0]} rotation={[Math.PI, 0, 0]}>
            <coneGeometry args={[0.5, 2, 16]} />
            <meshBasicMaterial color={color} transparent opacity={0.3} />
          </mesh>
          <spotLight
            position={[0, 0.3, 0]}
            angle={Math.PI / 6}
            penumbra={0.5}
            intensity={2}
            color={color}
            castShadow
          />
          {isSelected && (
            <mesh position={[0, 0.5, 0]}>
              <boxGeometry args={[0.9, 2.7, 0.9]} />
              <meshBasicMaterial color="#C6A85C" wireframe transparent opacity={0.3} />
            </mesh>
          )}
        </group>
      );

    case 'uplight':
      return (
        <group>
          <mesh position={[0, 0.5, 0]}>
            <boxGeometry args={[0.5, 1, 0.5]} />
            <meshBasicMaterial visible={false} />
          </mesh>
          <mesh castShadow>
            <cylinderGeometry args={[0.15, 0.1, 0.3, 16]} />
            <meshStandardMaterial color="#222222" metalness={0.5} />
          </mesh>
          <pointLight
            position={[0, 0.5, 0]}
            intensity={1.5}
            color={color}
            distance={5}
          />
          <mesh position={[0, 0.2, 0]}>
            <sphereGeometry args={[0.1, 8, 8]} />
            <meshBasicMaterial color={color} />
          </mesh>
          {isSelected && (
            <mesh position={[0, 0.5, 0]}>
              <boxGeometry args={[0.6, 1.2, 0.6]} />
              <meshBasicMaterial color="#C6A85C" wireframe transparent opacity={0.3} />
            </mesh>
          )}
        </group>
      );

    case 'signage':
      return (
        <group>
          <mesh position={[0, 1, 0]}>
            <boxGeometry args={[1.6, 2.2, 0.5]} />
            <meshBasicMaterial visible={false} />
          </mesh>
          <mesh position={[0, 1, 0]} castShadow>
            <boxGeometry args={[1.5, 2, 0.1]} />
            <meshStandardMaterial color="#8B4513" roughness={0.6} />
          </mesh>
          <mesh position={[0, 1, 0.06]} castShadow>
            <boxGeometry args={[1.3, 1.8, 0.05]} />
            <meshStandardMaterial color={color} {...matProps} />
          </mesh>
          <mesh position={[0, 0.5, -0.3]} rotation={[0.3, 0, 0]} castShadow>
            <cylinderGeometry args={[0.05, 0.05, 1.5, 8]} />
            <meshStandardMaterial color="#8B4513" />
          </mesh>
          {isSelected && (
            <mesh position={[0, 1, 0]}>
              <boxGeometry args={[1.7, 2.3, 0.6]} />
              <meshBasicMaterial color="#C6A85C" wireframe transparent opacity={0.3} />
            </mesh>
          )}
        </group>
      );

    case 'backdrop':
      return (
        <group>
          <mesh position={[0, 3, 0]}>
            <boxGeometry args={[8, 7, 1]} />
            <meshBasicMaterial visible={false} />
          </mesh>
          <mesh position={[-3.5, 3, 0]} castShadow>
            <cylinderGeometry args={[0.15, 0.15, 6, 16]} />
            <meshStandardMaterial color="#8B4513" roughness={0.6} />
          </mesh>
          <mesh position={[3.5, 3, 0]} castShadow>
            <cylinderGeometry args={[0.15, 0.15, 6, 16]} />
            <meshStandardMaterial color="#8B4513" roughness={0.6} />
          </mesh>
          <mesh position={[0, 6, 0]} rotation={[0, 0, Math.PI / 2]} castShadow>
            <cylinderGeometry args={[0.15, 0.15, 7, 16]} />
            <meshStandardMaterial color="#8B4513" roughness={0.6} />
          </mesh>
          <mesh position={[0, 3, 0]} castShadow receiveShadow>
            <planeGeometry args={[6.8, 5.8]} />
            <meshStandardMaterial color={color} {...matProps} side={THREE.DoubleSide} />
          </mesh>
          {isSelected && (
            <mesh position={[0, 3, 0]}>
              <boxGeometry args={[8.2, 7.2, 1.2]} />
              <meshBasicMaterial color="#C6A85C" wireframe transparent opacity={0.3} />
            </mesh>
          )}
        </group>
      );

    default:
      return (
        <mesh castShadow>
          <boxGeometry args={[1, 1, 1]} />
          <meshStandardMaterial color={color} />
        </mesh>
      );
  }
}
